            continue

        odds_val = row.get('odds')
        try:
            american_probability(odds_val)
        except (ValueError, TypeError):
            continue

        obs_str = row.get('observed_at')
        exp_str = row.get('expires_at')

        if not isinstance(obs_str, str) or not isinstance(exp_str, str):
            continue

        try:
            obs_dt = datetime.fromisoformat(obs_str.replace('Z', '+00:00'))
            exp_dt = datetime.fromisoformat(exp_str.replace('Z', '+00:00'))
        except ValueError:
            continue

        if obs_dt.tzinfo is None or exp_dt.tzinfo is None:
            continue

        if not (obs_dt < exp_dt):
            continue

        if not (obs_dt <= asof < exp_dt):
            continue

        if best_row is None or obs_dt > best_time or (obs_dt == best_time and row_id < best_id):
            best_row = row
            best_time = obs_dt
            best_id = row_id

    return best_row
